def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 8 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            minr = min(y for y, x in comp)
            maxr = max(y for y, x in comp)
            minc = min(x for y, x in comp)
            maxc = max(x for y, x in comp)

            if maxr - minr < 2 or maxc - minc < 2:
                continue

            perimeter = {
                (y, x)
                for y in range(minr, maxr + 1)
                for x in range(minc, maxc + 1)
                if y in (minr, maxr) or x in (minc, maxc)
            }
            if perimeter.issubset(set(comp)):
                fill = 7 if maxr - minr == 2 and maxc - minc == 2 else 2
                for y in range(minr + 1, maxr):
                    for x in range(minc + 1, maxc):
                        out[y][x] = fill

    return out
